def _extract_text_fragments(obj: Any) -> List[str]:
    parts: List[str] = []
    if isinstance(obj, str):
        parts.append(obj)
    elif isinstance(obj, dict):
        for v in obj.values():
            parts.extend(_extract_text_fragments(v))
    elif isinstance(obj, (list, tuple)):
        for v in obj:
            parts.extend(_extract_text_fragments(v))
    return parts
